using System;using System.IO;using System.Linq;using System.Collections;using System.Collections.Generic;using UnityEngine;using CatGunner.Recovery;
public static class PreviewPenguinActions
{
 static string Dir=>Path.GetFullPath(Application.dataPath+"/../../../art/reskin/penguin-expedition/grip-expression-v2/captures");
 public static string Capture(){var c=RecoveryForestClient.Instance;if(!Application.isPlaying||!c.SaveFolderOverride.Contains("PenguinPreview"))throw new Exception("Isolated preview required");Directory.CreateDirectory(Dir);c.StartCoroutine(Run(c));return "Recording actual short-wing grip, natural shooting, three penguins, costume variants and native stage victory.";}

 public static string Victory(){var c=RecoveryForestClient.Instance;if(!Application.isPlaying||!c.SaveFolderOverride.Contains("PenguinPreview"))throw new Exception("Isolated preview required");c.StartCoroutine(Win(c));return "Recording from first takeoff through all three smooth armed hops.";}
 static IEnumerator Win(RecoveryForestClient c){while(c.IsTransitioning||!c.ReadyForPlay)yield return null;var rows=Newtonsoft.Json.Linq.JArray.Parse(File.ReadAllText(Path.Combine(Dir,"frames.json")));foreach(var row in rows.Where(r=>(string)r["kind"]=="win").ToArray())row.Remove();c.Forest.Stage_Value_Max=c.Forest.Stage_Now*10+c.Forest.Level_Now;ForestRuntimeAcceptance.IsGaming=true;c.GameWin();var cg=c.WinUI.GetComponent<CanvasGroup>();if(cg==null)cg=c.WinUI.AddComponent<CanvasGroup>();float alpha=cg.alpha;cg.alpha=0;
 for(int i=0;i<34;i++){yield return new WaitForEndOfFrame();var m=c.Hero.GetComponentInChildren<PenguinBoneMotion>(true);var p=Camera.main.WorldToScreenPoint(c.Hero.transform.position);rows.Add(Newtonsoft.Json.Linq.JObject.FromObject(new{kind="win",index=i,time=Time.realtimeSinceStartup,x=p.x,y=Screen.height-p.y,shots=m.Shots,happy=m.VictoryStrength,jump=m.JumpAmount,focus=c.Hero.GetComponentInChildren<PenguinExpression>(true).Focus}));ScreenCapture.CaptureScreenshot(Path.Combine(Dir,"win-"+i.ToString("00")+".png"));yield return new WaitForSeconds(.03f);}cg.alpha=alpha;File.WriteAllText(Path.Combine(Dir,"frames.json"),rows.ToString());File.WriteAllText(Path.Combine(Dir,"victory-complete.txt"),"Actual GPU frames; native stage-win callback; full takeoff included; independent preview save; banner temporarily transparent for closeup only.");}
 static IEnumerator Shot(string n,float wait=.3f){yield return new WaitForSecondsRealtime(wait);yield return new WaitForEndOfFrame();ScreenCapture.CaptureScreenshot(Path.Combine(Dir,n+".png"));yield return null;}
 static IEnumerator Run(RecoveryForestClient c){var frames=new List<object>();void Record(string kind,int index){var m=c.Hero.GetComponentInChildren<PenguinBoneMotion>(true);var anchor=c.Hero.transform.position;var p=Camera.main.WorldToScreenPoint(anchor);frames.Add(new{kind,index,time=Time.realtimeSinceStartup,x=p.x,y=Screen.height-p.y,shots=m.Shots,happy=m.VictoryStrength,jump=m.JumpAmount,focus=c.Hero.GetComponentInChildren<PenguinExpression>(true).Focus});}while(!c.ReadyForPlay)yield return null;c.DailyLogin.AutoShow=false;c.DailyLogin.Close();c.Tutorial.SetCleared();c.Forest.Stage_Value_Max=400;c.ContentUnlock.Reload();foreach(int id in new[]{5,10,19})c.Inventory.AddRewardGun(id);c.Inventory.Equip(Array.FindIndex(c.State.Owned_Gun_list,g=>g==19),0);c.Inventory.Equip(Array.FindIndex(c.State.Owned_Gun_list,g=>g==5),1);c.Inventory.Equip(Array.FindIndex(c.State.Owned_Gun_list,g=>g==10),2);c.ApplyBalance();yield return Shot("01-main",3);
  for(int i=0;i<48;i++){yield return new WaitForEndOfFrame();Record("shoot",i);ScreenCapture.CaptureScreenshot(Path.Combine(Dir,"shoot-"+i.ToString("00")+".png"));yield return new WaitForSeconds(.045f);}
  c.Inventory.Equip(Array.FindIndex(c.State.Owned_Gun_list,g=>g==0),0);c.ApplyBalance();yield return new WaitForSeconds(.7f);
  for(int i=0;i<36;i++){yield return new WaitForEndOfFrame();Record("basic",i);ScreenCapture.CaptureScreenshot(Path.Combine(Dir,"basic-"+i.ToString("00")+".png"));yield return new WaitForSeconds(.035f);}
  foreach(int skin in new[]{13,17,21,24}){c.State.Skin_Unlock[skin]=true;c.Skins.Select(skin);c.Skins.Skin_List_UI.SetActive(false);c.Skins.skin_info_ui.gameObject.SetActive(false);yield return Shot("skin-"+skin.ToString("00"),.5f);}c.Skins.Select(0);c.Skins.Skin_List_UI.SetActive(false);c.Skins.skin_info_ui.gameObject.SetActive(false);yield return Shot("02-three-penguins",.5f);
  c.Forest.Stage_Value_Max=c.Forest.Stage_Now*10+c.Forest.Level_Now;ForestRuntimeAcceptance.IsGaming=true;c.GameWin();
  var group=c.WinUI.GetComponent<CanvasGroup>();if(group==null)group=c.WinUI.AddComponent<CanvasGroup>();float bannerAlpha=group.alpha;group.alpha=0;
  for(int i=0;i<34;i++){yield return new WaitForEndOfFrame();Record("win",i);ScreenCapture.CaptureScreenshot(Path.Combine(Dir,"win-"+i.ToString("00")+".png"));yield return new WaitForSeconds(.04f);}
  group.alpha=bannerAlpha;File.WriteAllText(Path.Combine(Dir,"frames.json"),Newtonsoft.Json.JsonConvert.SerializeObject(frames));File.WriteAllText(Path.Combine(Dir,"complete.json"),Newtonsoft.Json.JsonConvert.SerializeObject(new{source="Actual Unity Editor GPU frames",save=c.SaveFolderOverride,fixture="Isolated preview: native equipment and skins selected, native GameWin callback invoked once to preview transition. Physics/stats unchanged; no normal save writes. Win banner hidden only during closeup recording to avoid covering the penguin; its native active state is retained.",motions=c.Team.Cat_list.Select(cat=>{var m=cat.GetComponentInChildren<PenguinBoneMotion>(true);var w=cat.GetComponentInChildren<PenguinHoldingWing>(true);return new{m.Shots,m.VictoryCount,span=w.GripSpan/m.BodyHeight};}).ToArray(),width=Screen.width,height=Screen.height},Newtonsoft.Json.Formatting.Indented));
 }
}
